-- =====================================================================
-- OMS360 Enterprise AI Food Delivery Platform
-- Production-Quality Demo Data Seed Script
-- Database: oms360_db
-- MySQL 8.0 Compatible
-- Generated: Demo / Seed Data Only
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET AUTOCOMMIT = 0;

USE `oms360_db`;

-- =====================================================================
-- SCHEMA DEFINITIONS
-- =====================================================================

DROP TABLE IF EXISTS `inventory_alerts`;
DROP TABLE IF EXISTS `order_audit_trail`;
DROP TABLE IF EXISTS `inventory_ledger`;
DROP TABLE IF EXISTS `delivery_status`;
DROP TABLE IF EXISTS `kitchen_status`;
DROP TABLE IF EXISTS `transactions`;
DROP TABLE IF EXISTS `order_items`;
DROP TABLE IF EXISTS `orders_master`;
DROP TABLE IF EXISTS `inventory`;
DROP TABLE IF EXISTS `items`;

CREATE TABLE `items` (
  `item_id` VARCHAR(20) NOT NULL,
  `item_name` VARCHAR(150) NOT NULL,
  `price` DECIMAL(10,2) NOT NULL,
  `total_stock` INT NOT NULL DEFAULT 0,
  `remaining_stock` INT NOT NULL DEFAULT 0,
  `used_stock` INT NOT NULL DEFAULT 0,
  `status` VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `inventory` (
  `inventory_id` INT NOT NULL AUTO_INCREMENT,
  `item_id` VARCHAR(20) NOT NULL,
  `item_name` VARCHAR(150) NOT NULL,
  `total_stock` INT NOT NULL DEFAULT 0,
  `remaining_stock` INT NOT NULL DEFAULT 0,
  `used_stock` INT NOT NULL DEFAULT 0,
  `status` VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`inventory_id`),
  KEY `idx_inventory_item_id` (`item_id`),
  CONSTRAINT `fk_inventory_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `orders_master` (
  `order_id` VARCHAR(20) NOT NULL,
  `customer_id` VARCHAR(20) NOT NULL,
  `customer_name` VARCHAR(150) NOT NULL,
  `mobile_number` VARCHAR(15) NOT NULL,
  `delivery_address` VARCHAR(255) NOT NULL,
  `city` VARCHAR(50) NOT NULL,
  `order_total` DECIMAL(10,2) NOT NULL,
  `payment_method` VARCHAR(20) NOT NULL,
  `payment_status` VARCHAR(20) NOT NULL DEFAULT 'PAID',
  `fraud_status` VARCHAR(20) NOT NULL DEFAULT 'CLEAR',
  `order_status` VARCHAR(20) NOT NULL DEFAULT 'DELIVERED',
  `live_window_track` VARCHAR(30) NOT NULL DEFAULT 'SUCCESS_FLOW',
  `enterprise_id` VARCHAR(20) NOT NULL DEFAULT 'ENT-99',
  `order_date` DATETIME NOT NULL,
  PRIMARY KEY (`order_id`),
  KEY `idx_orders_customer` (`customer_id`),
  KEY `idx_orders_city` (`city`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `order_items` (
  `order_item_id` VARCHAR(20) NOT NULL,
  `order_id` VARCHAR(20) NOT NULL,
  `item_id` VARCHAR(20) NOT NULL,
  `item_name` VARCHAR(150) NOT NULL,
  `quantity` INT NOT NULL,
  `price` DECIMAL(10,2) NOT NULL,
  `item_total` DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (`order_item_id`),
  KEY `idx_orderitems_order` (`order_id`),
  KEY `idx_orderitems_item` (`item_id`),
  CONSTRAINT `fk_orderitems_order` FOREIGN KEY (`order_id`) REFERENCES `orders_master` (`order_id`),
  CONSTRAINT `fk_orderitems_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `transactions` (
  `transaction_id` VARCHAR(20) NOT NULL,
  `order_id` VARCHAR(20) NOT NULL,
  `transaction_amount` DECIMAL(10,2) NOT NULL,
  `payment_method` VARCHAR(20) NOT NULL,
  `payment_status` VARCHAR(20) NOT NULL DEFAULT 'PAID',
  `transaction_date` DATETIME NOT NULL,
  PRIMARY KEY (`transaction_id`),
  KEY `idx_txn_order` (`order_id`),
  CONSTRAINT `fk_txn_order` FOREIGN KEY (`order_id`) REFERENCES `orders_master` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `kitchen_status` (
  `kitchen_id` VARCHAR(20) NOT NULL,
  `order_id` VARCHAR(20) NOT NULL,
  `station_id` VARCHAR(20) NOT NULL,
  `chef_name` VARCHAR(50) NOT NULL,
  `status` VARCHAR(20) NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`kitchen_id`),
  KEY `idx_kitchen_order` (`order_id`),
  CONSTRAINT `fk_kitchen_order` FOREIGN KEY (`order_id`) REFERENCES `orders_master` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `delivery_status` (
  `delivery_id` VARCHAR(20) NOT NULL,
  `order_id` VARCHAR(20) NOT NULL,
  `rider_name` VARCHAR(50) NOT NULL,
  `status` VARCHAR(30) NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`delivery_id`),
  KEY `idx_delivery_order` (`order_id`),
  CONSTRAINT `fk_delivery_order` FOREIGN KEY (`order_id`) REFERENCES `orders_master` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `inventory_ledger` (
  `ledger_id` VARCHAR(20) NOT NULL,
  `order_id` VARCHAR(20) NOT NULL,
  `item_id` VARCHAR(20) NOT NULL,
  `movement_type` VARCHAR(20) NOT NULL,
  `quantity` INT NOT NULL,
  `remaining_stock_after` INT NOT NULL,
  `movement_date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ledger_id`),
  KEY `idx_ledger_order` (`order_id`),
  KEY `idx_ledger_item` (`item_id`),
  CONSTRAINT `fk_ledger_order` FOREIGN KEY (`order_id`) REFERENCES `orders_master` (`order_id`),
  CONSTRAINT `fk_ledger_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `order_audit_trail` (
  `audit_id` VARCHAR(20) NOT NULL,
  `order_id` VARCHAR(20) NOT NULL,
  `event_type` VARCHAR(30) NOT NULL,
  `event_time` DATETIME NOT NULL,
  PRIMARY KEY (`audit_id`),
  KEY `idx_audit_order` (`order_id`),
  CONSTRAINT `fk_audit_order` FOREIGN KEY (`order_id`) REFERENCES `orders_master` (`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `inventory_alerts` (
  `alert_id` VARCHAR(20) NOT NULL,
  `item_id` VARCHAR(20) NOT NULL,
  `item_name` VARCHAR(150) NOT NULL,
  `remaining_stock` INT NOT NULL,
  `alert_message` VARCHAR(255) NOT NULL,
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`alert_id`),
  KEY `idx_alerts_item` (`item_id`),
  CONSTRAINT `fk_alerts_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

